class _ColorMapping(dict):
    def __init__(self, init_mapping):
        super().__init__(init_mapping)
        self.cache = {}

    def __setitem__(self, k, v):
        super().__setitem__(k, v)
        self.cache.clear()

    def __delitem__(self, k):
        super().__delitem__(k)
        self.cache.clear()


